using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Creezio.Switcher;

internal static class ToolContractCompatibilityTests
{
    private const string Tag=" This tool is part of plugin `Sites`.";
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    private static TunnelTool Tool(){return new TunnelTool{Server="codex_apps",Name="sites.get_deployment_status",ConnectorId="sites-provider",Description="Read the deployment status.",ReadOnly=true,Annotations=Json.Read<object>("{\"readOnlyHint\":true,\"openWorldHint\":true,\"destructiveHint\":false}"),Schema=Json.Read<object>("{\"type\":\"object\",\"properties\":{\"project_id\":{\"type\":\"string\",\"description\":\"Exact site identifier.\"}},\"required\":[\"project_id\"],\"additionalProperties\":false}")};}
    private static TunnelTool Copy(TunnelTool tool){return Json.Read<TunnelTool>(Json.Write(tool));}
    private static void Changed(Action<TunnelTool> change){var saved=Tool();var live=Copy(saved);live.Description+=Tag;change(live);Assert(!ToolTunnel.SameContract(saved,live),"changed authorization contract accepted");}
    private static TunnelTool Remote(object required){var tool=Tool();tool.Name="sites.save_site_version";tool.ReadOnly=false;tool.Annotations=null;tool.Schema=Json.Read<object>("{\"type\":\"object\",\"properties\":{\"project_id\":{\"type\":\"string\"},\"commit_sha\":{\"type\":\"string\"},\"archive\":{\"type\":\"string\",\"description\":\"omit it only when local packaging cannot complete and remote build fallback is required.\"}}}");Json.Obj(tool.Schema)["required"]=required;return tool;}
    private sealed class Connection:IToolTunnelConnection
    {
        internal TunnelTool Live=Tool();internal int Calls;
        public Task<TunnelTool[]> Inventory(CancellationToken token){return Task.FromResult(new[]{Live});}
        public Task<object> Invoke(string server,string name,object args,CancellationToken token){Calls++;return Task.FromResult((object)new{isError=false,structuredContent=new{status="success"}});}
        public void Dispose(){}
    }
    private static void Dispatch(string root,bool drift)
    {
        string folder=Path.Combine(root,"compatibility-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
        var store=new RelayStore(folder);var connection=new Connection();var owner=new TunnelOwner{Id="owner",Name="Owner",Home=Path.Combine(folder,"owner"),Account="owner-account"};
        var session=new RelaySession{Home=Path.Combine(folder,"source"),Account="source-account",Thread="chat",Channel="source"};
        var tunnel=new ToolTunnel(store,id=>owner,o=>connection,s=>{});
        var grant=new TunnelGrant{Id=Guid.NewGuid().ToString("N"),Name="Existing Sites read",Instance="owner",Enabled=true,ResourceField="project_id",ResourceValue="site-1",Sources=new Dictionary<string,string>{{session.Home,session.Account}},Tools=new List<TunnelTool>{Copy(connection.Live)}};
        tunnel.SaveGrant(grant);string snapshot=File.ReadAllText(Path.Combine(folder,"tool-grants.dpapi"));
        connection.Live.Description+=Tag;if(drift)Json.Obj(connection.Live.Schema)["additionalProperties"]=true;
        var call=tunnel.Invoke(session,Guid.NewGuid().ToString("N"),grant.Id,"codex_apps",connection.Live.Name,new Dictionary<string,object>{{"project_id","site-1"}},CancellationToken.None).GetAwaiter().GetResult();
        Assert(call.State==(drift?"blocked":"completed")&&connection.Calls==(drift?0:1),"producer dispatch did not enforce the saved contract");
        Assert(snapshot==File.ReadAllText(Path.Combine(folder,"tool-grants.dpapi")),"authorization snapshot rewritten during invocation");
    }
    private static void OptionalDispatch(string root,bool useAdded,bool liveTransport)
    {
        string folder=Path.Combine(root,"compatible-option-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var store=new RelayStore(folder);var connection=new Connection();var owner=new TunnelOwner{Id="owner",Name="Owner",Home=Path.Combine(folder,"owner"),Account="owner-account"};var session=new RelaySession{Home=Path.Combine(folder,"source"),Account="source-account",Thread="fixture-chat",Channel="source"};var tunnel=new ToolTunnel(store,id=>owner,o=>connection,s=>{});
        var grant=new TunnelGrant{Id=Guid.NewGuid().ToString("N"),Name="Existing explicit read only",Instance="owner",Enabled=true,ResourceField="project_id",ResourceValue="site-1",Sources=new Dictionary<string,string>{{session.Home,session.Account}},Tools=new List<TunnelTool>{Copy(connection.Live)}};tunnel.SaveGrant(grant);string before=File.ReadAllText(Path.Combine(folder,"tool-grants.dpapi"));
        Json.Obj(Json.Get(connection.Live.Schema,"properties"))["new_option"]=Json.Read<object>("{\"type\":\"boolean\"}");connection.Live.Description="Refreshed provider documentation.";if(liveTransport)Json.Obj(Json.Get(Json.Get(connection.Live.Schema,"properties"),"project_id"))["description"]="An absolute local file path";
        var args=new Dictionary<string,object>{{"project_id","site-1"}};if(useAdded)args["new_option"]=true;var call=tunnel.Invoke(session,Guid.NewGuid().ToString("N"),grant.Id,"codex_apps",connection.Live.Name,args,CancellationToken.None).GetAwaiter().GetResult();bool blocked=useAdded||liveTransport;Assert(call.State==(blocked?"blocked":"completed")&&connection.Calls==(blocked?0:1),"Compatible update widened inputs or failed a legitimate existing invocation");Assert(before==File.ReadAllText(Path.Combine(folder,"tool-grants.dpapi")),"Live compatibility rewrote the user authorization");
        if(!blocked){Assert(call.ContractStatus=="compatible"&&Json.Write(ToolTunnel.Summary(call)).Contains("contractReason"),"Compatibility decision absent from durable diagnostics");var retry=tunnel.Invoke(session,call.Id,grant.Id,"codex_apps",connection.Live.Name,args,CancellationToken.None).GetAwaiter().GetResult();Assert(retry.State=="completed"&&connection.Calls==1,"Compatible request retry repeated the operation");}
    }
    internal static void RunAll(Action<string,Action> check,string root)
    {
        check("contract accepts one exact terminal Sites attribution in either direction",()=>{var a=Tool();var b=Copy(a);b.Description+=Tag;Assert(ToolTunnel.SameContract(a,b)&&ToolTunnel.SameContract(b,a),"attribution blocked unchanged contract");});
        check("contract attribution compatibility leaves global signatures and objects unchanged",()=>{var a=Tool();var b=Copy(a);b.Description+=Tag;string sa=ToolTunnel.Signature(a),sb=ToolTunnel.Signature(b),before=Json.Write(new[]{a,b});Assert(sa!=sb&&ToolTunnel.SameContract(a,b)&&ToolTunnel.Signature(a)==sa&&ToolTunnel.Signature(b)==sb&&Json.Write(new[]{a,b})==before,"normalization altered immutable signature or inputs");});
        check("contract presentation changes do not alter granted operations",()=>{var saved=Tool();var live=Copy(saved);live.Description="Updated documentation, same operation and risk metadata."+Tag;Assert(ToolTunnel.SameContract(saved,live),"Description alone invalidated an unchanged permission contract");});
        check("contract parameter documentation drift preserves the exact executable constraints",()=>{var saved=Tool();var live=Copy(saved);Json.Obj(Json.Get(Json.Get(live.Schema,"properties"),"project_id"))["description"]="Updated wording of the same identifier.";Assert(ToolTunnel.SameContract(saved,live),"Parameter documentation required reauthorization");});
        check("contract rejects schema required and additionalProperties drift",()=>{Changed(t=>Json.Obj(t.Schema)["required"]=new[]{"project_id","deployment_id"});Changed(t=>Json.Obj(t.Schema)["additionalProperties"]=true);});
        check("contract rejects changed risk annotations and read-only declaration",()=>{foreach(string name in new[]{"readOnlyHint","openWorldHint","destructiveHint"})Changed(t=>Json.Obj(t.Annotations)[name]=!Object.Equals(Json.Get(t.Annotations,name),true));Changed(t=>t.ReadOnly=false);});
        check("contract rejects changed or absent Sites connector identity",()=>{Changed(t=>t.ConnectorId="different");Changed(t=>t.ConnectorId=null);var a=Tool();a.ConnectorId=null;var b=Copy(a);b.Description+=Tag;Assert(!ToolTunnel.SameContract(a,b),"missing connector normalized");a.ConnectorId=" ";b=Copy(a);b.Description+=Tag;Assert(!ToolTunnel.SameContract(a,b),"blank connector normalized");});
        check("contract presentation compatibility is generic but never changes tool identity",()=>{foreach(string name in new[]{"chatgpt_space.read_page","Sites.get_deployment_status","sites_other.get_deployment_status"}){var a=Tool();a.Name=name;var b=Copy(a);b.Description+=Tag;Assert(ToolTunnel.SameContract(a,b),"Presentation compatibility depended on a plugin name");}var c=Tool();c.Server="another-provider";var d=Copy(c);d.Description+=Tag;Assert(ToolTunnel.SameContract(c,d),"Other provider documentation required reauthorization");Changed(t=>t.Name="sites.get_site");Changed(t=>t.Server="another-provider");});
        check("contract presentation labels punctuation and whitespace do not grant permissions",()=>{foreach(string tag in new[]{" This tool is part of plugin `Pages`."," This tool is part of plugin `sites`."," This tool is part of plugin `Sites`",Tag+" ","this tool is part of plugin `Sites`."}){var a=Tool();var b=Copy(a);b.Description+=tag;Assert(ToolTunnel.SameContract(a,b),"Display wording invalidated a stable contract");}});
        check("contract repeated attribution is presentation metadata only",()=>{var a=Tool();foreach(string description in new[]{a.Description+Tag+" More behavior.",a.Description+Tag+Tag}){var b=Copy(a);b.Description=description;Assert(ToolTunnel.SameContract(a,b),"Attribution text invalidated unchanged tool");}var once=Copy(a);once.Description+=Tag;var twice=Copy(once);twice.Description+=Tag;Assert(ToolTunnel.SameContract(once,twice),"Repeated label required a new grant");Assert(ToolTunnel.SameContract(twice,Copy(twice)),"identical strict contract rejected");});
        check("contract supports canonically equal metadata with one Sites attribution",()=>{var a=Tool();var b=Copy(a);b.Description+=Tag;b.Annotations=Json.Read<object>("{\"destructiveHint\":false,\"openWorldHint\":true,\"readOnlyHint\":true}");b.Schema=Json.Read<object>("{\"additionalProperties\":false,\"required\":[\"project_id\"],\"properties\":{\"project_id\":{\"description\":\"Exact site identifier.\",\"type\":\"string\"}},\"type\":\"object\"}");Assert(ToolTunnel.SameContract(a,b),"equivalent metadata rejected");});
        check("Sites remote build supports equivalent ArrayList array and list required names",()=>{foreach(object value in new object[]{new object[]{"project_id","commit_sha"},new ArrayList{"project_id","commit_sha"},new List<string>{"commit_sha","project_id"}})Assert(ToolTunnel.SupportsSitesRemoteBuild(Remote(value)),"runtime collection changed capability");});
        check("Sites remote build rejects scalar dictionary null and malformed required",()=>{foreach(object value in new object[]{null,"project_id",new Dictionary<string,object>{{"project_id",true},{"commit_sha",true}},12,new object[]{"project_id",null},new ArrayList{"project_id",42},new object[]{"project_id",""}})Assert(!ToolTunnel.SupportsSitesRemoteBuild(Remote(value)),"malformed required accepted");});
        check("Sites remote build rejects missing extra duplicate and case-changed required names",()=>{foreach(object value in new object[]{new object[0],new[]{"project_id"},new[]{"project_id","commit_sha","archive"},new[]{"project_id","project_id"},new[]{"project_id","Commit_sha"},new[]{"project_id","approval"}})Assert(!ToolTunnel.SupportsSitesRemoteBuild(Remote(value)),"required contract widened");});
        check("existing authorized Sites read with optional attribution invokes producer once",()=>Dispatch(root,false));
        check("real Sites schema drift still blocks producer before invocation",()=>Dispatch(root,true));
        check("contract permits only unused new optional inputs without defaults",()=>{var a=Tool();var b=Copy(a);Json.Obj(Json.Get(b.Schema,"properties"))["new_option"]=Json.Read<object>("{\"type\":\"boolean\"}");Assert(ToolTunnel.SameContract(a,b)&&ToolTunnel.ContractDifference(a,b,new Dictionary<string,object>{{"project_id","site-1"}})==null,"Unused optional input broke previous callers");Assert(ToolTunnel.ContractDifference(a,b,new Dictionary<string,object>{{"project_id","site-1"},{"new_option",true}})!=null,"New input was silently authorized");Json.Obj(Json.Get(Json.Get(b.Schema,"properties"),"new_option"))["default"]=false;Assert(!ToolTunnel.SameContract(a,b),"New default behavior was silently accepted");});
        check("contract rejects required removal changed types bounds and removed inputs",()=>{Changed(t=>Json.Obj(t.Schema)["required"]=new string[0]);Changed(t=>Json.Obj(Json.Get(Json.Get(t.Schema,"properties"),"project_id"))["type"]="number");Changed(t=>Json.Obj(Json.Get(Json.Get(t.Schema,"properties"),"project_id"))["maxLength"]=10);Changed(t=>Json.Obj(Json.Get(t.Schema,"properties")).Remove("project_id"));});
        check("contract metadata keys inside literal defaults const or unknown keywords remain protected",()=>{foreach(string key in new[]{"const","default","x-authorization-policy"}){var a=Tool();Json.Obj(a.Schema)[key]=Json.Read<object>("{\"description\":\"before\",\"title\":\"before\"}");var b=Copy(a);Json.Obj(Json.Get(b.Schema,key))["description"]="after";Assert(!ToolTunnel.SameContract(a,b),"Literal executable data was treated as presentation metadata");}});
        check("contract validates property map shape and preserves properties named description",()=>{Changed(t=>Json.Obj(t.Schema)["properties"]=new object[0]);Changed(t=>Json.Obj(t.Schema)["properties"]="invalid");var a=Tool();Json.Obj(Json.Get(a.Schema,"properties"))["description"]=Json.Read<object>("{\"type\":\"string\"}");var b=Copy(a);Json.Obj(Json.Get(Json.Get(b.Schema,"properties"),"description"))["type"]="number";Assert(!ToolTunnel.SameContract(a,b),"An actual property named description was omitted");});
        check("contract required and enum ordering are semantic sets",()=>{var a=Tool();Json.Obj(a.Schema)["required"]=new[]{"project_id","other"};Json.Obj(a.Schema)["enum"]=new[]{"one","two"};var b=Copy(a);Json.Obj(b.Schema)["required"]=new[]{"other","project_id"};Json.Obj(b.Schema)["enum"]=new[]{"two","one"};Assert(ToolTunnel.SameContract(a,b),"Reordered sets required user reauthorization");});
        check("contract optional nested array inputs remain outside previous authorization",()=>{var a=Tool();a.Schema=Json.Read<object>("{\"type\":\"object\",\"properties\":{\"rows\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"old\":{\"type\":\"string\"}},\"additionalProperties\":true}}}}");var b=Copy(a);var item=Json.Get(Json.Get(Json.Get(b.Schema,"properties"),"rows"),"items");Json.Obj(Json.Get(item,"properties"))["new_option"]=Json.Read<object>("{\"type\":\"boolean\"}");Assert(ToolTunnel.SameContract(a,b),"Nested unused optional property rejected");Assert(ToolTunnel.ContractDifference(a,b,Json.Read<object>("{\"rows\":[{\"old\":\"fixture\",\"new_option\":true}]}"))!=null,"Nested array silently gained a new authorized input");});
        check("contract optional additions in referenced definitions stay closed without resolution",()=>{var a=Tool();a.Schema=Json.Read<object>("{\"type\":\"object\",\"$defs\":{\"Row\":{\"type\":\"object\",\"properties\":{\"old\":{\"type\":\"string\"}}}},\"properties\":{\"row\":{\"$ref\":\"#/$defs/Row\"}}}");var b=Copy(a);Json.Obj(Json.Get(Json.Get(Json.Get(b.Schema,"$defs"),"Row"),"properties"))["new_option"]=Json.Read<object>("{\"type\":\"boolean\"}");Assert(!ToolTunnel.SameContract(a,b),"Unresolved reference widened an input surface");});
        check("compatible optional evolution invokes producer once without updating any grant",()=>OptionalDispatch(root,false,false));
        check("optional provider additions cannot be used through an older explicit grant",()=>OptionalDispatch(root,true,false));
        check("compatible documentation still enforces the current native transport restrictions",()=>OptionalDispatch(root,false,true));
    }
}
